if (!params) params = {};

const currentTabName = $ctrl.uiState.currentTab.name;

const {
    entityType = currentTabName,
    page = $ctrl.tabStore[currentTabName].currentPage,
    query = $ctrl.uiState.currentFilter.currentFilterString
} = params;

let apiQuery = $ctrl.filterService.buildCombinedQuery({
    advancedFilters: $ctrl.uiState.currentFilter.advancedFilters
});

if ($ctrl.tabConfig[entityType]?.isCompanyBound) {

    if (entityType === 'attendance_summary') {
        try {
            const workerOpts = await $ctrl.referenceDataService.dropdownOptionsGetters.getOptions("Worker");
            $ctrl.referenceData.workerMap = workerOpts;

            const workerIds = workerOpts.map(opt => opt.value);

            if (workerIds.length > 0) {
                apiQuery += `&WorkerId_in=${workerIds.join(',')}`;
            } else {
                apiQuery += `&Id_eq=-1`;
            }
        } catch (err) {
            console.warn("Failed to fetch workers for attendance summary company filtering", err);
            apiQuery += `&Id_eq=-1`;
        }
    }

    else {
        apiQuery += `&CompanyId=${$ctrl.globalSelectedCompany.companyId}`;
    }
}

await $ctrl.baseGridControllerService.loadGridData($ctrl, {
    entityType,
    customEntityKey: $ctrl.tabConfig[entityType]?.customEntityKey,
    columnDefs: $ctrl.tabConfig[entityType].columnDefaultConfig,
    page,
    limit: $ctrl.tabStore[entityType].limit,
    query: apiQuery,
    hydrateOnLoad: true
});

try {
    // Fetch formatted options directly from service
    const [payScheduleOpts, payPeriodOpts] = await Promise.all([
        $ctrl.referenceDataService.dropdownOptionsGetters.getOptions("PaySchedule"),
        $ctrl.referenceDataService.dropdownOptionsGetters.getOptions("PayPeriod")
    ]);

    // workerMap is being populated already in loadActiveTab, so removing it from here.
    $ctrl.referenceData.payScheduleMap = payScheduleOpts;
    $ctrl.referenceData.payPeriodMap = payPeriodOpts;

} catch (e) {
    console.warn("Background reference load failed", e);
}

const previewBox = document.getElementById("file-preview");
const errorDisplay = document.getElementById("errors-and-warnings");

if ($ctrl.form.file) {
    window.Papa.parse($ctrl.form.file, {
        complete: (results) => {
            const data = results.data;
            const maxLines = 100;
            const previewData = data.slice(0, maxLines);
            renderTable(previewData, data.length > maxLines);
        },
        error: (err) => {
            previewBox.innerHTML = `<p style="color:red;">Error parsing CSV: ${err.message}</p>`;
        }
    });
} else {
    if (previewBox) previewBox.innerHTML = ``;
    if (errorDisplay) errorDisplay.innerHTML = ``;
    if ($ctrl.hasErrors) $ctrl.hasErrors = false;
}

function renderTable(data, isTruncated) {
    if (!data || data.length === 0) {
        previewBox.innerHTML = "<p>No data to display.</p>";
        return;
    }

    // Create table element
    let table = `<table style="width: 100%; ">`;
    table += "<thead><tr>";

    // Add header row
    data[0].forEach(header => {
        table += `<th style="text-align: left; ">${header}</th>`;
    });
    table += "</tr></thead>";

    // Add data rows
    table += "<tbody>";
    for (let i = 1; i < data.length; i++) {
        table += "<tr>";
        data[i].forEach(cell => {
            table += `<td style="text-align: left; ">${cell}</td>`;
        });
        table += "</tr>";
    }
    table += "</tbody></table>";

    // Add truncation message if applicable
    if (isTruncated) {
        table += "<p>... (preview truncated)</p>";
    }

    waitForElementAndInject(table);
}

function waitForElementAndInject(table) {
    let element = document.getElementById("file-preview");

    if (element) {
        element.innerHTML = table;
    } else {
        $ctrl.$timeout(waitForElementAndInject(table), 100);
    }
}

$ctrl.uiState.isSaving = true;
const endpoint = $ctrl.authCookies.serverUrl.concat('/attendance_summary');

if ($ctrl.form.file) {
    const formData = new FormData();
    formData.append('attendanceSummaryCSV', $ctrl.form.file, $ctrl.form.file.name);
    formData.append('PayPeriodId', $ctrl.form.payPeriodId);
    formData.append('allowNegativeBalance', $ctrl.form.allowNegativeBalance);
    formData.append('validateOnly', true);

    await fetch(endpoint, {
        method: 'POST',
        headers: $ctrl.authCookies.setHeaders(),
        body: formData
    })
        .then(response => {
            if (!response.ok) {
                return response.json().then(errData => {
                    throw new Error(JSON.stringify(errData));
                });
            }
            return response.json();
        })
        .then(result => {
            const errorDisplay = document.getElementById("errors-and-warnings");
            if (errorDisplay) errorDisplay.innerHTML = ``;
            if ($ctrl.uiState.csvHasErrors) $ctrl.uiState.csvHasErrors = false;
            window.Papa.parse($ctrl.form.file, {
                complete: (results) => {
                    const data = results.data;
                    const maxLines = 100;
                    const previewData = data.slice(0, maxLines);

                    $ctrl.$modal.open("confirm-csv-modal", { props: { FileName: $ctrl.form.file.name, PreviewData: previewData, DataLength: data.length } })
                        .then(response => {
                            if ($ctrl.form.file && response.result === "ok") {
                                $ctrl.isGettingEntities = true;

                                const formData = new FormData();
                                formData.append('attendanceSummaryCSV', $ctrl.form.file, $ctrl.form.file.name);
                                formData.append('PayPeriodId', $ctrl.form.payPeriodId);
                                formData.append('allowNegativeBalance', $ctrl.form.allowNegativeBalance);
                                formData.append('validateOnly', false);

                                fetch(endpoint, {
                                    method: 'POST',
                                    headers: $ctrl.authCookies.setHeaders(),
                                    body: formData
                                })
                                    .then(response => {
                                        if (!response.ok) {
                                            return response.json().then(errData => {
                                                throw new Error(JSON.stringify(errData));
                                            });
                                        }
                                        return response.json();
                                    })
                                    .then(result => {
                                        $ctrl.utils.toast(`Successfully Uploaded Attendance`, "OK");
                                        $ctrl.loaders.loadActiveTab();
                                        $ctrl.formManagementService.onFormClose($ctrl.uiState);

                                        $ctrl.utils.resetForm($ctrl.form);
                                        if ($ctrl.uiState.csvHasErrors) document.getElementById("errors-and-warnings").innerHTML = "";
                                        $ctrl.uiState.csvHasErrors = false;
                                    })
                                    .catch(error => {
                                        $ctrl.uiState.csvHasErrors = true;
                                        $ctrl.utils.toast(`Errors Found.`, "ERROR");
                                        const errors = JSON.parse(error.message)?.errors || ["An unexpected error occurred"];
                                        let errorDisplay = "";
                                        errors.forEach(err => {
                                            errorDisplay += `
                <p style="font-weight: bold; ">Line ${err.LineNumber}: <span style="font-weight: normal; font-style: underline; ">${err.Row}</span></p>
                ${err.messages.map(msg => `<li>${msg}</li>`).join("")}
                <hr>
                `;
                                        });
                                        waitForElementAndInject(errorDisplay);
                                    })
                            }
                        });
                },
                error: (err) => {
                    previewBox.innerHTML = `<p style="color:red;">Error parsing CSV: ${err.message}</p>`;
                }
            });
        })
        .catch(error => {
            $ctrl.uiState.csvHasErrors = true;
            $ctrl.utils.toast(`Errors Found.`, "ERROR");
            const errors = JSON.parse(error.message)?.errors || ["An unexpected error occurred"];
            let errorDisplay = "";
            errors.forEach(err => {
                errorDisplay += `
                <p style="font-weight: bold; ">Line ${err.LineNumber}: <span style="font-weight: normal; font-style: underline; ">${err.Row}</span></p>
                ${err.messages.map(msg => `<li>${msg}</li>`).join("")}
                <hr>
                `;
            });
            waitForElementAndInject(errorDisplay);
        })
        .finally(() => {
            if ($ctrl.uiState.isSaving) $ctrl.uiState.isSaving = false;
        });
}

function waitForElementAndInject(errors) {
    const element = document.getElementById("errors-and-warnings");
    if (element) {
        element.innerHTML = "";
        element.innerHTML += errors;
    } else {
        $ctrl.$timeout(() => waitForElementAndInject(errors), 100);
    }
}

const config = $ctrl.tabConfig[$ctrl.uiState.currentTab.name];
if (!config) {
    console.error("No configuration found for current tab:", $ctrl.uiState.currentTab.name);
    return;
}

const isUpdate = $ctrl.uiState.isEditingExistingEntity;
const method = isUpdate ? "PUT" : "POST";
const formData = $ctrl[config.form];

let displayName = "Item";
if (config.getName) {
    displayName = config.getName(formData);
} else if (config.entityNameKey) {
    displayName = formData[config.entityNameKey] || "Item";
}

const additionalData = {};
if (config.companyBound && method === "POST") {
    additionalData.CompanyId = $ctrl.globalSelectedCompany.companyId;
}

$ctrl.uiState.isSaving = true;

await $ctrl.entityOperationsService.executeEntityOperation(
    method,
    formData,
    async (result) => { // onSuccess
        // Reload Grid
        if (method === "POST") {
            $ctrl.loaders.loadActiveTab({ isAfterWrite: true });
            $ctrl.formManagementService.onFormClose($ctrl.uiState);
            $ctrl.utils.resetForm(formData);
        } else {
            const tableRowIndex = $ctrl.tabStore[$ctrl.uiState.currentTab.name].data.findIndex(entity => entity.Id === $ctrl.uiState.selectedEntity.Id);
            if (tableRowIndex === -1) {
                $ctrl.loaders.loadActiveTab({ isAfterWrite: true });
                throw new Error(`Entity not found in table`);
            }

            $ctrl.tabStore[$ctrl.uiState.currentTab.name].data[tableRowIndex] = $ctrl.uiState.selectedEntity = $ctrl.utils.buildUpdatedEntityData(formData, $ctrl.uiState.selectedEntity);
            const hydratedEntity = await $ctrl.referenceDataService.hydrateEntity(
                $ctrl.tabStore[$ctrl.uiState.currentTab.name].data[tableRowIndex]
            );
            $ctrl.tabStore[$ctrl.uiState.currentTab.name].data[tableRowIndex] = $ctrl.uiState.selectedEntity = hydratedEntity;
            $ctrl.uiState.selectedEntityName = $ctrl.uiState.selectedEntity.Worker + "'s " + $ctrl.uiState.selectedEntity.EarningCode;
            $ctrl.utils.reselectEntityAfterUpdate({
                timeout: $ctrl.$timeout,
                rowIndex: tableRowIndex,
                formManagementService: $ctrl.formManagementService, 
                uiState: $ctrl.uiState,
                form: $ctrl[$ctrl.tabConfig[$ctrl.uiState.currentTab.name].form] 
            });
        }
    },
    null,
    () => { // onFinally
        $ctrl.uiState.isSaving = false;
    },
    $ctrl.uiState.currentTab.name,
    displayName,
    $ctrl.uiState.selectedEntity,
    additionalData
);

const entityName = $ctrl.uiState.selectedEntityName || "Item";

await $ctrl.entityOperationsService.confirmDelete($ctrl.uiState.selectedEntity, entityName)
    .then(confirmed => {
        if (!confirmed) return;

        $ctrl.uiState.isDeleting = true;

        return $ctrl.entityOperationsService.executeEntityOperation(
            "DELETE",           // Method
            null,               // No form data
            () => {             // Success
                $ctrl.loaders.loadActiveTab();
                $ctrl.uiState.selectedEntity = null;
            },
            null,               // Error
            () => {             // Finally
                $ctrl.uiState.isDeleting = false;
            },
            $ctrl.uiState.currentTab.name,       // EntityType
            entityName,         // Display Name
            $ctrl.uiState.selectedEntity
        );
    });

$ctrl.baseGridControllerService.handleRowSelection($ctrl, row, {

    uiState: $ctrl.uiState,
    utils: $ctrl.utils,
    referenceService: $ctrl.referenceDataService,
    viewService: $ctrl.entityViewService,
    gridData: $ctrl.tabStore[$ctrl.uiState.currentTab.name]?.data,

    config: {
        mappers: {
            "CalculationMethodId": (val) => (val === 1 ? "FLAT" : "PERCENT")
        }
    },
});
